INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `SoundType`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(36915, 0, 0, 'Relax, friend. You have not passed away... yet. Sadly, these others cannot say the same.', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Erunak Stonespeaker to Player'),
(39313, 0, 0, 'You ssserve or you die, sssoftsskin!', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Zin\'jatar Raider'),
(39313, 1, 0, 'You cannot hide, breather!', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Zin\'jatar Raider to Player'),
(39313, 2, 0, 'Sshe will find you....', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Zin\'jatar Raider to Player'),
(39460, 0, 0, 'Budd! Noooo!', 14, 0, 100, 0, 0, 20915, 0, 0, 0, 'Adarrah'),
(39460, 1, 0, 'Captain! Shipwreck off the starboard bow! There appear to be survivors!', 14, 0, 100, 397, 0, 20916, 0, 0, 0, 'Adarrah'),
(39478, 0, 0, 'Come aboard, now. Step right up!\n', 14, 0, 100, 3, 0, 21279, 0, 0, 0, 'Mack Fearsen'),
(39478, 1, 0, 'Cap\'n Samir is navigatin\' this here ship non-stop to that there ocean over yonder...\n', 14, 0, 100, 22, 0, 21280, 0, 0, 0, 'Mack Fearsen'),
(39478, 2, 0, '...where we\'ll commence to assistin\' the Alliance in their little skirmish with them Horde fellers.\n', 14, 0, 100, 22, 0, 21281, 0, 0, 0, 'Mack Fearsen'),
(39478, 3, 0, 'Easy money! Commission\'s to be dispersed evenly among any and all survivors!\n', 14, 0, 100, 22, 0, 21282, 0, 0, 0, 'Mack Fearsen'),
(39478, 4, 0, 'Aww, Budd. Now what\'d ya go an\' do that for?\n', 12, 0, 100, 6, 0, 20915, 0, 0, 0, 'Mack Fearsen'),
(39478, 5, 0, 'What the... ?', 12, 0, 100, 5, 0, 21278, 0, 0, 0, 'Mack Fearsen'),
(39480, 0, 0, 'Ahoy!', 14, 0, 100, 22, 0, 21174, 0, 0, 0, 'Budd'),
(39480, 1, 0, 'I\'m saaaailing!', 14, 0, 100, 22, 0, 21175, 0, 0, 0, 'Budd'),
(39480, 2, 0, 'Out on a boat... way far away from the dock...\n', 12, 0, 100, 1, 0, 21176, 0, 0, 0, 'Budd'),
(39480, 3, 0, 'Into the wind with the sky and everything...\n', 12, 0, 100, 1, 0, 21177, 0, 0, 0, 'Budd'),
(39480, 4, 0, 'Oooh... shiny!', 12, 0, 100, 397, 0, 21178, 0, 0, 0, 'Budd'),
(40601, 0, 0, 'To the depths with you, beast!', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Erunak Stonespeaker to Player'),
(40601, 1, 0, 'Hold on, $r!', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Erunak Stonespeaker to Player'),
(42021, 0, 0, 'See those ships in dock?', 12, 0, 100, 25, 0, 21333, 0, 0, 0, 'Stormwind Soldier to Stormwind Recruit'),
(42021, 1, 0, 'They\'re the only ones that have returned from battle, and they\'re being repaired.', 12, 0, 100, 396, 0, 21334, 0, 0, 0, 'Stormwind Soldier to Stormwind Recruit'),
(42021, 2, 0, 'I don\'t like it either, but it boils down to this...', 12, 0, 100, 396, 0, 21335, 0, 0, 0, 'Stormwind Soldier to Stormwind Recruit'),
(42021, 3, 0, 'We pay the mercs to get us out there, or our troops get no reinforcements.', 12, 0, 100, 396, 0, 21336, 0, 0, 0, 'Stormwind Soldier to Stormwind Recruit'),
(42021, 4, 0, 'Welcome to the military, recruit.', 12, 0, 100, 396, 0, 21337, 0, 0, 0, 'Stormwind Soldier to Stormwind Recruit'),
(42021, 5, 0, 'Put all of that out of your head, recruit.\n', 12, 0, 100, 396, 0, 21343, 0, 0, 0, 'Stormwind Soldier to Stormwind Recruit'),
(42021, 6, 0, 'I\'ve been fightin\' Horde for ten years now, and I\'ve never seen it worse than this.', 12, 0, 100, 396, 0, 21342, 0, 0, 0, 'Stormwind Soldier to Stormwind Recruit'),
(42021, 7, 0, 'Just stay focused on the battle in front of us, or you won\'t live to worry about the rest.', 12, 0, 100, 396, 0, 21344, 0, 0, 0, 'Stormwind Soldier to Stormwind Recruit'),
(42021, 8, 0, 'I stopped by the park district on my way here. There\'s nothing left of it...\n', 12, 0, 100, 396, 0, 21351, 0, 0, 0, 'Stormwind Soldier to Totally Generic Bunny (All Phase)'),
(42021, 9, 0, 'Aye. I was here when the dragon attacked.', 12, 0, 100, 396, 0, 21353, 0, 0, 0, 'Stormwind Soldier to Stormwind Soldier'),
(42021, 10, 0, 'He could\'ve destroyed the entire city if he willed it. We were powerless to stop him.', 12, 0, 100, 1, 0, 22801, 0, 0, 0, 'Stormwind Soldier to Stormwind Soldier'),
(42021, 11, 0, 'What drove him off, then?', 12, 0, 100, 6, 0, 21352, 0, 0, 0, 'Stormwind Soldier to Totally Generic Bunny (All Phase)'),
(42021, 12, 0, 'No idea. It made no sense...', 12, 0, 100, 1, 0, 21355, 0, 0, 0, 'Stormwind Soldier to Stormwind Soldier'),
(42021, 13, 0, 'He flew in, torched the park, then just flew off.', 12, 0, 100, 1, 0, 21356, 0, 0, 0, 'Stormwind Soldier to Stormwind Soldier'),
(42021, 14, 0, 'If you ask me, the beast is insane.', 12, 0, 100, 396, 0, 21357, 0, 0, 0, 'Stormwind Soldier to Stormwind Soldier'),
(42022, 0, 0, 'Why must we ride to battle on a mercenary ship? Used to be that we\'d kill pirates as soon as look at them.', 12, 0, 100, 6, 0, 21325, 0, 0, 0, 'Stormwind Recruit to Totally Generic Bunny (All Phase)'),
(42022, 1, 0, 'That makes sense, I suppose. Just doesn\'t feel right...', 12, 0, 100, 396, 0, 21326, 0, 0, 0, 'Stormwind Recruit to Totally Generic Bunny (All Phase)'),
(42059, 0, 0, 'Earthquakes every other day, a crazy dragon tearing up the world, what\'s next?', 12, 0, 100, 6, 0, 21327, 0, 0, 0, 'Stormwind Recruit to Totally Generic Bunny (All Phase)'),
(42059, 1, 0, 'Yessir.', 12, 0, 100, 24, 0, 21328, 0, 0, 0, 'Stormwind Recruit to Totally Generic Bunny (All Phase)'),
(42095, 0, 0, 'Make what out, exactly?', 12, 0, 100, 6, 0, 21329, 0, 0, 0, 'Stormwind Recruit to Stormwind Soldier'),
(42095, 1, 0, 'Have you been there?', 12, 0, 100, 6, 0, 21330, 0, 0, 0, 'Stormwind Recruit to Totally Generic Bunny (All Phase)'),
(42095, 2, 0, 'Yeah, I... I think I can see it too.', 12, 0, 100, 6, 0, 21331, 0, 0, 0, 'Stormwind Recruit to Captain Taylor'),
(42096, 0, 0, 'I think I can just make it out from here. Right on the edge of the horizon.', 12, 0, 100, 25, 0, 21345, 0, 0, 0, 'Stormwind Soldier to Totally Generic Bunny (All Phase)'),
(42096, 1, 0, 'The new island - just surfaced after the last earthquakes.', 12, 0, 100, 1, 0, 21346, 0, 0, 0, 'Stormwind Soldier to Totally Generic Bunny (All Phase)'),
(42096, 2, 0, 'It\'s what we\'re fighting for. On this front, at least.', 12, 0, 100, 1, 0, 21347, 0, 0, 0, 'Stormwind Soldier to Totally Generic Bunny (All Phase)'),
(42096, 3, 0, 'This\'ll be my third time now.', 12, 0, 100, 273, 0, 21348, 0, 0, 0, 'Stormwind Soldier to Totally Generic Bunny (All Phase)'),
(42096, 4, 0, 'Toughest fighting I\'ve seen...', 12, 0, 100, 1, 0, 21349, 0, 0, 0, 'Stormwind Soldier to Totally Generic Bunny (All Phase)'),
(42096, 5, 0, 'We lose that island to the Horde and Stormwind\'s as good as gone... and they know it.', 12, 0, 100, 1, 0, 21350, 0, 0, 0, 'Stormwind Soldier to Totally Generic Bunny (All Phase)'),
(42103, 0, 0, 'That\'s enough, soldier.', 12, 0, 100, 1, 0, 21207, 0, 0, 0, 'Captain Taylor to Totally Generic Bunny (All Phase)'),
(42103, 1, 0, 'Now get your minds right! We\'ll be killing orcs within the hour.', 12, 0, 100, 1, 0, 21208, 0, 0, 0, 'Captain Taylor to Totally Generic Bunny (All Phase)'),
(42103, 2, 0, 'Listen up! Our transport should be here momentarily.', 14, 0, 100, 22, 0, 21204, 0, 0, 0, 'Captain Taylor to Totally Generic Bunny (All Phase)'),
(42103, 3, 0, 'Fall in!', 14, 0, 100, 22, 0, 21205, 0, 0, 0, 'Captain Taylor to Totally Generic Bunny (All Phase)'),
(42103, 4, 0, 'Alright, men! Move out!', 14, 0, 100, 4, 0, 21206, 0, 0, 0, 'Captain Taylor'),
(42103, 5, 0, 'Civilians...', 12, 0, 100, 6, 0, 21183, 0, 0, 0, 'Captain Taylor'),
(42103, 6, 0, 'Fall in, men!', 14, 0, 100, 22, 0, 21184, 0, 0, 0, 'Captain Taylor'),
(42103, 7, 0, 'That island on the horizon is our destination.', 12, 0, 100, 1, 0, 21185, 0, 0, 0, 'Captain Taylor'),
(42103, 8, 0, 'It\'s where we will do our duty, for our king, for Stormwind and for her people...', 12, 0, 100, 1, 0, 21186, 0, 0, 0, 'Captain Taylor'),
(42103, 9, 0, 'Every orc you slay today will bring honor to them, and to every soldier who has come before you.', 12, 0, 100, 1, 0, 21187, 0, 0, 0, 'Captain Taylor'),
(42103, 10, 0, 'Hellscream has sent his best to take this island. We shall see to it that none return home...', 12, 0, 100, 1, 0, 21188, 0, 0, 0, 'Captain Taylor'),
(42103, 11, 0, 'Today Hellscream shall learn the lesson that Thrall failed to teach him...', 12, 0, 100, 1, 0, 21189, 0, 0, 0, 'Captain Taylor'),
(42103, 12, 0, 'Stormwind shall never fall!', 12, 0, 100, 53, 0, 21190, 0, 0, 0, 'Captain Taylor'),
(42103, 13, 0, 'Now make ready, for soon we\'ll be ashore.', 12, 0, 100, 1, 0, 21191, 0, 0, 0, 'Captain Taylor'),
(39866, 0, 0, 'Thanks, friend. We owe ya one.', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Captain Samir to Player'),
(39866, 1, 0, 'Hang in there, Mack...', 12, 0, 100, 432, 0, 0, 0, 0, 0, 'Captain Samir to Player'),
(39868, 0, 0, 'Come inside, $r. I must repay your kindness.', 12, 0, 100, 396, 0, 0, 0, 0, 0, 'Adarrah to Player'),
(39884, 0, 0, 'Woohooo!', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Captain Samir to Player'),
(39996, 0, 0, 'Grab the Seahorse while it\'s distracted!', 42, 0, 100, 0, 0, 0, 0, 0, 0, 'Abyssal Seahorse to Player'),
(39996, 1, 0, 'The Abyssal Seahorse seems very displeased.', 16, 0, 100, 0, 0, 0, 0, 0, 0, 'Abyssal Seahorse'),
(39996, 2, 0, 'Hold on tight!\n\n|TInterface\\Icons\\misc_arrowlup.blp:32|t', 42, 0, 100, 0, 0, 0, 0, 0, 0, 'Abyssal Seahorse to Player'),
(39996, 3, 0, '', 42, 0, 100, 0, 0, 0, 0, 0, 0, 'Abyssal Seahorse to Player'),
(39996, 4, 0, 'Lean right!\n\n|TInterface\\Icons\\misc_arrowright.blp:32|t', 42, 0, 100, 0, 0, 0, 0, 0, 0, 'Abyssal Seahorse to Player'),
(39996, 5, 0, 'Lean left!\n\n|TInterface\\Icons\\misc_arrowleft.blp:32|t', 42, 0, 100, 0, 0, 0, 0, 0, 0, 'Abyssal Seahorse to Player'),
(40105, 0, 0, 'Well done, $n! I imagine your journeys beneath the waves will be much smoother from here out.', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Erunak Stonespeaker to Player'),
(40677, 0, 0, 'You got shiny?', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Gilblin Scavenger to 178449'),
(40690, 0, 0, 'Die, beast!', 14, 0, 100, 0, 0, 0, 0, 0, 0, 'Captain Taylor to Player'),
(40690, 1, 0, 'We\'ve been discovered... Hurry $n, there\'s little time!', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Captain Taylor to Player'),
(40690, 2, 0, 'To battle, men!', 14, 0, 100, 53, 0, 0, 0, 0, 0, 'Captain Taylor to Player'),
(40691, 0, 0, 'Captain! The naga! They\'ve followed $n back to the ship!', 14, 0, 100, 5, 0, 0, 0, 0, 0, 'Stormwind Soldier to Player'),
(40696, 0, 0, 'For Stormwind!', 14, 0, 100, 0, 0, 0, 0, 0, 0, 'Stormwind Soldier to Player'),
(40701, 0, 0, 'Sssoftsskinss! Sssoon you shall ssserve my Lady!', 14, 0, 100, 0, 0, 0, 0, 0, 0, 'Zin\'jatar Scout to Player'),
(40729, 0, 0, 'Brace yourselves, men!', 14, 0, 100, 0, 0, 0, 0, 0, 0, 'Captain Taylor to Briny Cutter Battle Bunny'),
(40729, 1, 0, 'Make them pay!', 14, 0, 100, 0, 0, 0, 0, 0, 0, 'Captain Taylor to Briny Cutter Battle Bunny'),
(40729, 2, 0, 'Stay alert! Don\'t let them drag you away!', 14, 0, 100, 0, 0, 0, 0, 0, 0, 'Captain Taylor to Briny Cutter Battle Bunny'),
(40729, 3, 0, 'Don\'t give up! Fight! Fight for the Alliance!', 14, 0, 100, 0, 0, 0, 0, 0, 0, 'Captain Taylor to Briny Cutter Battle Bunny'),
(40729, 4, 0, 'Their numbers are... endless...', 14, 0, 100, 0, 0, 0, 0, 0, 0, 'Captain Taylor to Briny Cutter Battle Bunny'),
(40729, 5, 0, 'My men - they\'re all taken... Go! Save youselves!', 14, 0, 100, 0, 0, 0, 0, 0, 0, 'Captain Taylor to Briny Cutter Battle Bunny'),
(40731, 0, 0, 'Gah... heeelp!', 14, 0, 100, 0, 0, 0, 0, 0, 0, 'Stormwind Seal to Zin\'jatar Abductor'),
(40734, 0, 0, 'No! Ahhhhh.....', 14, 0, 100, 0, 0, 0, 0, 0, 0, 'Stormwind Seal to Zin\'jatar Abductor'),
(40737, 0, 0, 'There are too many! Shaman, do something!', 14, 0, 100, 0, 0, 0, 0, 0, 0, 'Captain Taylor to Briny Cutter Battle Bunny'),
(40737, 1, 0, 'Rest while you can, men. That wasn\'t the last of them....', 14, 0, 100, 0, 0, 0, 0, 0, 0, 'Captain Taylor to Briny Cutter Battle Bunny'),
(40797, 0, 0, 'What a fine ssspecimen you are.', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Zin\'jatar Abductor to Player'),
(40797, 1, 0, 'My Lady will be mosst grateful for my effortsss.', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Zin\'jatar Abductor to Player'),
(40801, 0, 0, 'We were most fortunate to escape, $n. Follow me.', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Erunak Stonespeaker to Player'),
(40810, 0, 0, 'We kill them and we take their stuffs...', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Gilblin Scavenger to Player'),
(41017, 0, 0, 'What you bring us? Treasures from the surface?', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Gilblin Collector to Player'),
(41018, 0, 0, 'You got shiny?', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'King Gurboggle to Player'),
(41098, 0, 0, '|cFFFF2222Fire Harpoon Gun!|r', 42, 0, 100, 0, 0, 0, 0, 0, 0, 'Gnaws to Player'),
(41328, 0, 0, 'We have arrived, $n. Does he still live?', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Erunak Stonespeaker to Player'),
(41331, 0, 0, 'This should warm the lad up!', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Rendel Firetongue to Player'),
(41339, 0, 0, 'Who are you? What is this place?', 12, 0, 100, 0, 0, 0, 0, 0, 0, 'Private Pollard to Player'),
(46316, 0, 0, 'Leave Smuggler\'s Scar to signal Adarrah', 42, 0, 100, 0, 0, 0, 0, 0, 0, 'Gimme Shelter Kill Credit 00 to Player'),
(46463, 0, 0, 'Farewell, friend! Good treasure hunting!', 12, 0, 100, 70, 0, 0, 0, 0, 0, 'Budd to Player');
